from typing import Dict, List, Union, Any
from time import sleep

from taf.ul.alarms_watchdog import alarms_watchdog
from taf.ul.alarms_watchdog.exceptions import AlarmInactive, AlarmActive

from taf.rfrl.procedures.resources.python.bts.components.bts_component import BtsComponent
from taf.rfrl.procedures.resources.python.bts.components.component_collection import ComponentCollection
from taf.rfrl.procedures.resources.python.bts.components.du.du import Du
from taf.rfrl.procedures.resources.python.bts.config.config_cu import ConfigCu
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import log_info, pretty_log, log_debug
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import UnsupportedState, UnsupportedAlarm, UnexpectedAlarm
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import ApiResponse, CuApi, DuApi, DuConfig, CuConfig
from taf.rfrl.procedures.resources.python.bts.utils.ip import check_if_ip_is_reachable_via_https


class Cu(BtsComponent):
    """ Represents generic Central Unit. """

    _MISSING_ALARM_ATTRS_ERROR_MSG = 'No alarm attributes were provided for alarm on {} but at least one must be used'

    def __init__(self,
                 cu_info: ApiResponse,
                 api_cu: CuApi,
                 api_du: DuApi,
                 api_cu_alias: str,
                 api_du_aliases: Dict[str, str],
                 dus_init_configs: List[DuConfig],
                 cu_init_config: CuConfig,
                 cu_alarms_watchdog: Union[None, alarms_watchdog] = None):
        """
        :param cu_info: information about this CU received as a response to API request;
                        must contain following data:
                        {'name': 'vCU1_KRK'}
        :param api_cu: API used for performing CU-related operations
        :param api_du: API used for performing DU-related operations
        :param api_cu_alias: name of opened CU API connection which this CU should use
        :param api_du_aliases: names of all opened DU API connections which this CU should use;
                               names should be mapped to DU IDs, i.e. {'1': 'CloudBts140115122321672:DU1',
                                                                       '2': 'CloudBts140115122321672:DU2'}
        :param dus_init_configs: configuration details, taken from init file, of DUs connected to this CU
        :param cu_init_config: configuration details of this CU, taken from init file
        :param cu_alarms_watchdog: alarms watchdog instance used for watching alarms on this CU;
                                   defaults to None (new instance will be created)
        """
        log_info('Creating new CU')
        super(Cu, self).__init__(cu_info['name'])
        self._api_cu = api_cu
        self._api_du = api_du
        self._api_cu_alias = api_cu_alias
        self._api_du_aliases = api_du_aliases
        self._dus_init_configs = dus_init_configs
        self._cu_init_config = cu_init_config
        self._alarms_watchdog = cu_alarms_watchdog if cu_alarms_watchdog else alarms_watchdog()
        self._config = ConfigCu(mrbts_id=cu_info['mrbts_id'],
                                nrbts_id=cu_info['nrbts_id'],
                                api=api_cu,
                                api_alias=api_cu_alias)
        self._dus = ComponentCollection()
        log_debug(f'CU details:\n'
                  f'name={self._name}\n')

    def __eq__(self, other):
        return self._name == other.name

    @property
    def string_representation(self):
        info = f'  {self._name}:'

        for du in self._dus:
            info += f'\n{du.string_representation}'

        return info

    @property
    def alarms_watchdog(self) -> alarms_watchdog:
        """ Returns Alarms Watchdog used for watching alarms on this CU. """
        return self._alarms_watchdog

    @property
    def dus(self) -> ComponentCollection:
        """ Returns all DUs connected to this CU. """
        return self._dus

    @property
    def config(self) -> ConfigCu:
        """ Returns configuration (parameters and their values) of this CU. """
        return self._config

    @pretty_log
    def load(self, dus_alarms_watchdog: Union[Dict[int, Any], None] = None):
        """
        Loads all components currently connected to this CU.
        Each time current CU configuration changes (i.e. due to recomissioning which adds/removes BTS component)
        CU needs to be reloaded using this method.
        :param dus_alarms_watchdog: dictionary of DUs alarms watchdogs used for watching alarms on DUs connected to
                                    this CU; keys are DU instance IDs, values are alarms watchdog instances;
                                    if empty dict is passed then DUs will have new alarms watchdogs created;
                                    should not be set to None if CU was reloaded;
                                    defaults to None (if alarms watchdog exists for DU it will be saved and used
                                    further);
        """
        log_info(f'Loading {self._name}', to_console=True)

        if dus_alarms_watchdog is None:
            dus_alarms_watchdog = {du.instance_id: du.alarms_watchdog for du in self._dus}

        self._dus.clear()
        if self._dus_init_configs:
            dus_info = self._api_cu.get_dus_diff(connection=self._api_cu_alias)['created']

            for du_info in dus_info:
                du_id = du_info['id']
                du_init_id = int(du_id) - 1
                du_init_config = self._dus_init_configs[du_init_id]
                du_instance_id = du_init_config.instance_id
                du_alarms_watchdog = dus_alarms_watchdog[du_instance_id] if du_instance_id in dus_alarms_watchdog else None
                du = Du(parent=self,
                        du_info=du_info,
                        api=self._api_du,
                        api_alias=self._api_du_aliases[du_id],
                        du_init_config=du_init_config,
                        du_alarms_watchdog=du_alarms_watchdog)
                du.load()
                self._dus.append(du)

    @pretty_log
    def is_alarm_active(self, timeout: int = 0, **expected_attributes: str) -> bool:
        """
        Informs whether alarm with given attributes becomes active.
        :param timeout: time (in seconds) in which alarm should become active;
                        defaults to 0 (alarm should be active now)
        :param expected_attributes: keyword arguments representing alarm attributes and their expected values which
                                    should be used during active alarm verification;
                                    i.e. fault_id='49'
        :return: True if alarm with all provided attributes becomes active, False otherwise
        :raises UnsupportedAlarm: if no expected attributes are provided
        """
        return self._is_alarm_active(timeout, **expected_attributes)

    @pretty_log
    def check_active_alarm(self, timeout: int = 0, **expected_attributes: str):
        """
        Checks whether alarm with given attributes becomes active.
        :param timeout: time (in seconds) in which alarm should become active;
                        defaults to 0 (alarm should be active now)
        :param expected_attributes: keyword arguments representing alarm attributes and their expected values which
                                    should be used during active alarm verification;
                                    i.e. fault_id='49'
        :raises UnexpectedAlarm: if alarm with all provided attributes doesn't become active
        :raises UnsupportedAlarm: if no expected attributes are provided
        """
        alarm_is_active = self._is_alarm_active(timeout, **expected_attributes)

        if not alarm_is_active:
            raise UnexpectedAlarm(f'Expected alarm was not active on {self._name}')

    @pretty_log
    def is_alarm_inactive(self, timeout: int = 0, **expected_attributes: str) -> bool:
        """
        Informs whether alarm with given attributes becomes inactive.
        :param timeout: time (in seconds) in which alarm should become inactive;
                        defaults to 0 (alarm should be inactive now)
        :param expected_attributes: keyword arguments representing alarm attributes and their expected values which
                                    should be used during inactive alarm verification;
                                    i.e. fault_id='49'
        :return: True if alarm with all provided attributes becomes inactive, False otherwise
        :raises UnsupportedAlarm: if no expected attributes are provided
        """
        return self._is_alarm_inactive(timeout, **expected_attributes)

    @pretty_log
    def check_inactive_alarm(self, timeout: int = 0, **expected_attributes: str):
        """
        Checks whether alarm with given attributes becomes inactive.
        :param timeout: time (in seconds) in which alarm should become inactive;
                        defaults to 0 (alarm should be inactive now)
        :param expected_attributes: keyword arguments representing alarm attributes and their expected values which
                                    should be used during inactive alarm verification;
                                    i.e. fault_id='49'
        :raises UnexpectedAlarm: if alarm with all provided attributes doesn't become inactive
        :raises UnsupportedAlarm: if no expected attributes are provided
        """
        alarm_is_inactive = self._is_alarm_inactive(timeout, **expected_attributes)

        if not alarm_is_inactive:
            raise UnexpectedAlarm(f'Expected alarm is still active on {self._name}')

    @pretty_log
    def allow_alarm(self, **alarm_attributes: str):
        """
        Adds alarm with given attributes to list of allowed alarms on this CU.
        From now on such alarm will not be detected as disallowed if it becomes active.
        :param alarm_attributes: keyword arguments representing alarm attributes and their expected values which
                                 should be used during allowing alarm;
                                 i.e. fault_id='49'
        :raises UnsupportedAlarm: if no alarm attributes are provided
        """
        self._check_alarm_attributes(alarm_attributes)
        self._alarms_watchdog.allow_alarm(**alarm_attributes)

    @pretty_log
    def disallow_alarm(self, **alarm_attributes: str):
        """
        Removes alarm with given attributes from list of allowed alarms on this CU.
        From now on such alarm will be detected as disallowed if it becomes active.
        :param alarm_attributes: keyword arguments representing alarm attributes and their expected values which
                                 should be used during disallowing alarm;
                                 i.e. fault_id='49'
        :raises UnsupportedAlarm: if no alarm attributes are provided
        """
        self._check_alarm_attributes(alarm_attributes)
        self._alarms_watchdog.disallow_alarm(**alarm_attributes)

    @pretty_log
    def collect_snapshot(self, path: str):
        """
        Collects snapshot from this CU and stores it on local machine.
        :param path: absolute path to directory where snapshot should be stored; i.e. '/home/ute/logs'
        """
        log_info(f'Collecting snapshot from {self._name}', to_console=True)
        log_debug(f'Snapshot will bo stored in {path}')
        self._api_cu.get_local_snapshot(directory=path,
                                        compressed=True,
                                        connection=self._api_cu_alias)

    @pretty_log
    def check_if_reachable(self, delay: int = 0, timeout: int = 5):
        """
        Checks whether this CU is reachable via HTTPS.
        :param delay: time (in seconds) to wait before checking if CU is reachable;
                      defaults to 0 (no delay)
        :param timeout: time (in seconds) for CU to become reachable;
                        defaults to 5
        :raises ResultError: if CU doesn't become reachable before the timeout
        """
        self._check_if_reachable(delay, timeout)

    def _get_expected_statuses(self, state: str) -> Dict[str, str]:
        expected_statuses = {'on_air': {'operational_state': 'enabled'}}

        if state not in expected_statuses:
            raise UnsupportedState(self._UNSUPPORTED_STATE_ERROR_MSG.format(state, self._name))

        return expected_statuses[state]

    def _get_current_statuses(self, statuses_names: List[str]) -> Dict[str, str]:
        current_statuses = {}
        cu_info = self._api_cu.get_cu_state(connection=self._api_cu_alias)

        for status_name in statuses_names:
            current_status_value = cu_info.get(status_name)
            current_statuses[status_name] = current_status_value

        return current_statuses

    def _is_alarm_active(self, timeout: int = 0, **expected_attributes: str) -> bool:
        self._check_alarm_attributes(expected_attributes)
        self._log_details_of_expected_active_alarm(timeout, expected_attributes)

        if timeout:
            try:
                return self._alarms_watchdog.wait_for_active_alarm(timeout=timeout, **expected_attributes)
            except AlarmInactive:
                return False
        else:
            return self._alarms_watchdog.is_alarm_active(**expected_attributes)

    def _is_alarm_inactive(self, timeout: int = 0, **expected_attributes: str) -> bool:
        self._check_alarm_attributes(expected_attributes)
        self._log_details_of_expected_inactive_alarm(timeout, expected_attributes)

        if timeout:
            try:
                return self._alarms_watchdog.wait_for_inactive_alarm(timeout=timeout, **expected_attributes)
            except AlarmActive:
                return False
        else:
            return not self._alarms_watchdog.is_alarm_active(**expected_attributes)

    def _check_alarm_attributes(self, expected_attributes: Dict[str, str]):
        if not expected_attributes:
            raise UnsupportedAlarm(self._MISSING_ALARM_ATTRS_ERROR_MSG.format(self._name))

    def _log_details_of_expected_active_alarm(self, timeout: int, expected_attributes: Dict[str, str]):
        timeout_msg = f" before {timeout}s timeout" if timeout else ""
        log_info(f'Checking if expected alarm is active on {self._name}{timeout_msg}', to_console=True)
        log_debug(f'{self._name} expected active alarm: \n{expected_attributes}')

    def _log_details_of_expected_inactive_alarm(self, timeout: int, expected_attributes: Dict[str, str]):
        timeout_msg = f" before {timeout}s timeout" if timeout else ""
        log_info(f'Checking if expected alarm is inactive on {self._name}{timeout_msg}', to_console=True)
        log_debug(f'{self._name} expected active alarm: \n{expected_attributes}')

    def _check_if_reachable(self, delay: int, timeout: int):
        timeout_msg = f" before {timeout}s timeout" if timeout else ""
        log_info(f'Checking if {self._name} is reachable{timeout_msg}', to_console=True)
        sleep(delay)
        check_if_ip_is_reachable_via_https(ip=self._cu_init_config.oam_http_connection_details.addr, timeout=timeout)
